style.css:
@-moz-document domain("music.youtube.com") {
/* tùy chỉnh hiệu ứng */
    ytmusic-player-page {
        --my-blur: 38px;
        --my-zoom: 1.4;
        --my-brightness: 0.55;
        --my-purple: rgba(110, 0, 180, 0.22);

        background: #100817 !important;
    }

    /* phóng to và làm mờ ảnh nền */
    ytmusic-player-page #background {
        transform: scale(var(--my-zoom)) !important;
        filter:
            blur(var(--my-blur))
            brightness(var(--my-brightness))
            saturate(1.5) !important;
        opacity: 0.95 !important;
        transition: filter 0.5s ease !important;
    }

    /* phủ màu tím */
    ytmusic-player-page #background::after {
        content: "" !important;
        position: absolute !important;
        inset: 0 !important;
        background: var(--my-purple) !important;
        pointer-events: none !important;
    }

    /* giữ ảnh thumbnail chính sắc nét */
    ytmusic-player-page #player-page {
        filter: none !important;
    }

    /* chuyển cảnh mượt */
    ytmusic-player-page #background {
        transition:
            transform 0.6s ease,
            filter 0.6s ease !important;
    }
}
